<script setup lang="ts">import { onMounted, reactive, ref } from 'vue';import { api } from '../api';import { useAuthStore } from '../stores/auth';import { ElMessage } from 'element-plus';const auth=useAuthStore(),rows=ref<any[]>([]),dialog=ref(false),form=reactive<any>({taskId:null,hours:1,workDate:new Date().toISOString().slice(0,10),description:''});async function load(){rows.value=(await api.workLogs()).items}onMounted(load);function create(){Object.assign(form,{id:null,taskId:null,hours:1,workDate:new Date().toISOString().slice(0,10),description:''});dialog.value=true}async function save(){await api.saveWorkLog(form);dialog.value=false;ElMessage.success('已提交');load()}async function review(id:number,ok:boolean){await api.review(id,ok);load()}</script>
<template><div class="page"><div class="page-header"><h1 class="page-title">工时管理</h1><el-button type="primary" @click="create">登记工时</el-button></div><section class="card"><el-table :data="rows"><el-table-column prop="taskId" label="任务 ID"/><el-table-column prop="hours" label="工时"/><el-table-column prop="workDate" label="日期"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="150"><template #default="s"><span v-if="!auth.isManager">—</span><template v-else-if="s.row.status==='pending'"><el-button link type="success" @click="review(s.row.id,true)">通过</el-button><el-button link type="danger" @click="review(s.row.id,false)">驳回</el-button></template></template></el-table-column></el-table></section><el-dialog v-model="dialog" title="登记工时"><el-form label-width="90"><el-form-item label="任务 ID"><el-input-number v-model="form.taskId" :min="1"/></el-form-item><el-form-item label="工时"><el-input-number v-model="form.hours" :min="0.5" :step="0.5"/></el-form-item><el-form-item label="日期"><el-date-picker v-model="form.workDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">提交</el-button></template></el-dialog></div></template>
